begin;
create function pg_temp.p21_require(ok boolean)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'P21 SQL boundary assertion failed';end if;end$$;
create function pg_temp.p21_rejects(command text,code text)returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'Expected P21 rejection %',code;end$$;
grant execute on function pg_temp.p21_require(boolean),pg_temp.p21_rejects(text,text)to authenticated;
select pg_temp.p21_require((select bool_and(relrowsecurity)from pg_class where oid=any(array['public.tracking_counters'::regclass,'public.request_revisions'::regclass,'public.request_drafts'::regclass,'public.restricted_request_payloads'::regclass,'public.request_finance_values'::regclass,'public.workflow_instances'::regclass,'public.request_assignment_shells'::regclass,'public.request_events'::regclass])));
select pg_temp.p21_require(not has_function_privilege('anon','public.read_request(uuid,uuid,integer,integer)','execute')and not has_function_privilege('service_role','public.submit_request(uuid,jsonb,bigint,date,text,integer,uuid)','execute'));
select set_config('p21.scope',(select work_item_id::text from public.requests where request_type_id is not null limit 1),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333331',true);
select pg_temp.p21_require(not exists(select 1 from public.requests where request_type_id is not null));
select pg_temp.p21_require(not exists(select 1 from public.work_items where id=current_setting('p21.scope')::uuid));
select pg_temp.p21_rejects('select * from public.request_revisions','42501');
select pg_temp.p21_rejects('select * from public.restricted_request_payloads','42501');
select pg_temp.p21_rejects('select * from public.request_finance_values','42501');
select pg_temp.p21_rejects('select * from public.request_drafts','42501');
select pg_temp.p21_rejects('select * from public.workflow_instances','42501');
select pg_temp.p21_rejects('select * from public.request_assignment_shells','42501');
select pg_temp.p21_rejects('select * from public.tracking_counters','42501');
select pg_temp.p21_rejects('select * from public.request_events','42501');
select pg_temp.p21_rejects('select app_private.request_owned('||quote_literal(current_setting('p21.scope'))||')','42501');
select 'ok - P21_A3 raw table/RLS/spine/helper access denied independently of requester UI' as tap;
rollback;
